def agent_action(sandbox, agent_body, step_count):
    target = sandbox.get_target_speed()
    omega_measured = sandbox.get_wheel_angular_velocity()
    error = target - omega_measured

    # Calculate maximum torque based on current speed
    if omega_measured < 3:
        T_max = 3.5 + 15.5 * omega_measured
    else:
        T_max = 50.0

    # Check for stall condition (speed below 0.3 rad/s)
    if omega_measured < 0.3:
        # Apply maximum torque to overcome resistance
        torque = T_max
        # Clamp to torque deadzone (3 N·m)
        if abs(torque) < 3:
            torque = 0.0
        else:
            torque = max(-T_max, min(T_max, torque))
    else:
        # Proportional control with gain
        K = 2.0  # Tunable gain for speed regulation
        torque = K * error
        # Clamp to deadzone and torque limit
        if abs(torque) < 3:
            torque = 0.0
        else:
            torque = max(-T_max, min(T_max, torque))

    # Apply torque to the wheel
    sandbox.apply_motor_torque(torque)

